<script setup>
import {ref,onMounted} from 'vue'
import {request} from '../utils/request.js'
const roles=ref([]),permissions=ref([]),users=ref([]),error=ref(''),success=ref(''),busy=ref(false),query=ref(''),selectedRole=ref(null),selectedPermissions=ref([]),selectedUser=ref(null),selectedRoles=ref([]),page=ref(1),total=ref(0)
const draft=ref({role_code:'',role_name:'',description:''})
async function run(fn){if(busy.value)return;busy.value=true;error.value='';success.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function loadUsers(){const r=await request('/api/d1/admin/users?'+new URLSearchParams({q:query.value,page:page.value,page_size:20}));users.value=r.items;total.value=r.total}
async function loadRoles(){roles.value=await request('/api/d1/roles')}
function selectRole(r){selectedRole.value=r;selectedPermissions.value=[...r.permissions]}
function selectUser(u){selectedUser.value=u;selectedRoles.value=[...u.roles]}
async function saveRole(){await run(async()=>{await request(`/api/d1/roles/${selectedRole.value.id}/permissions`,{method:'PUT',body:{permission_codes:selectedPermissions.value}});await loadRoles();success.value='角色权限已更新，下次请求立即生效'})}
async function saveUser(){await run(async()=>{await request(`/api/d1/users/${selectedUser.value.id}/roles`,{method:'PUT',body:{role_codes:selectedRoles.value}});await loadUsers();success.value='用户角色已更新';selectedUser.value=null})}
async function create(){await run(async()=>{await request('/api/d1/roles',{method:'POST',body:draft.value});draft.value={role_code:'',role_name:'',description:''};await loadRoles();success.value='角色已创建，请配置权限后分配给用户'})}
onMounted(()=>run(async()=>{permissions.value=await request('/api/d1/permissions');await loadRoles();await loadUsers()}))
</script>
<template><div><h1>角色与权限管理</h1><p>创建业务角色、配置权限，并分配给用户。系统管理员角色受到保护。</p><p role="alert">{{error}}</p><p role="status">{{success}}</p><fieldset :disabled="busy"><section><h2>创建角色</h2><form @submit.prevent="create"><label>角色编码<input v-model="draft.role_code" pattern="[A-Z][A-Z0-9_]{1,49}" required placeholder="例如 CAMPUS_OPERATOR"></label><label>名称<input v-model="draft.role_name" required maxlength="50"></label><label>说明<input v-model="draft.description" maxlength="255"></label><button>创建角色</button></form></section><section><h2>角色权限</h2><button v-for="r in roles" :key="r.id" @click="selectRole(r)">{{r.role_name}}</button><div v-if="selectedRole"><h3>{{selectedRole.role_name}}</h3><p v-if="selectedRole.role_code==='SYSTEM_ADMIN'">受保护的系统管理员角色不可在此修改。</p><template v-else><label v-for="p in permissions" :key="p.id" class="choice"><input type="checkbox" :value="p.permission_code" v-model="selectedPermissions">{{p.description}} <small>{{p.permission_code}}</small></label><button @click="saveRole">保存权限</button></template></div></section><section><h2>用户角色分配</h2><form @submit.prevent="run(async()=>{page=1;await loadUsers()})"><input v-model="query" placeholder="用户名或昵称"><button>搜索</button></form><table><thead><tr><th>账号</th><th>角色</th><th>操作</th></tr></thead><tbody><tr v-for="u in users" :key="u.id"><td>{{u.username}}（{{u.id}}）</td><td>{{u.roles.join('、')||'暂无角色'}}</td><td><button @click="selectUser(u)">设置角色</button></td></tr></tbody></table><button :disabled="page===1" @click="run(async()=>{page--;await loadUsers()})">上一页</button><span>第 {{page}} 页 · 共 {{total}} 人</span><button :disabled="page*20>=total" @click="run(async()=>{page++;await loadUsers()})">下一页</button><div v-if="selectedUser"><h3>{{selectedUser.username}} 的角色</h3><label v-for="r in roles" :key="r.id" class="choice"><input type="checkbox" :value="r.role_code" v-model="selectedRoles">{{r.role_name}}</label><button @click="saveUser">保存角色</button></div></section></fieldset></div></template>
<style scoped>section{background:white;border:1px solid #ddd;border-radius:12px;padding:24px;margin:20px 0}fieldset{border:0;padding:0}label{display:inline-block;margin:8px}input:not([type=checkbox]){display:block;padding:8px}button{padding:8px 14px;margin:6px}.choice{display:block}table{width:100%;text-align:left}td,th{padding:10px;border-bottom:1px solid #eee}small{color:#667}</style>
